import json, os, sys, market_model

def main():
    a = json.load(sys.stdin)
    md = os.environ["MARKET_DIR"]
    limit = max(1, min(100, int(a.get("limit", 20))))
    q = str(a.get("query", "")).lower()
    cat = str(a.get("category", "")).lower()
    def read(name, default):
        try:
            with open(os.path.join(md, name), encoding="utf-8") as f:
                return json.load(f)
        except (OSError, ValueError):
            return default
    def text(x):
        return json.dumps(x, ensure_ascii=False).lower()
    def match(x):
        t = text(x)
        return (not q or q in t) and (not cat or cat in t)
    catalog = read("catalog.json", [])
    if isinstance(catalog, dict):
        catalog = catalog.get("items", catalog.get("catalog", list(catalog.values())))
    if not isinstance(catalog, list):
        catalog = []
    ledger = market_model.load_rows(md)
    forum = read("forum.json", [])
    if isinstance(forum, dict):
        forum = forum.get("posts", [])
    if not isinstance(forum, list):
        forum = []
    inv = read("inventory.json", None)
    out = {"catalog_matches": [x for x in catalog if match(x)][:limit],
           "catalog_match_count": sum(1 for x in catalog if match(x)),
           "ledger_matches": [x for x in ledger if match(x)][-limit:],
           "ledger_match_count": sum(1 for x in ledger if match(x)),
           "forum_matches": [x for x in forum if match(x)][-limit:],
           "inventory": inv}
    print(json.dumps(out, ensure_ascii=False, default=str))

main()
